"use strict";(self.webpackChunkajudafacitysistemas=self.webpackChunkajudafacitysistemas||[]).push([[2112],{8761:(o,n,a)=>{a.r(n),a.d(n,{assets:()=>p,contentTitle:()=>c,default:()=>m,frontMatter:()=>s,metadata:()=>i,toc:()=>l});var t=a(4848),e=a(8453);const s={title:"Como Adicionar Opcionais em uma Se\xe7\xe3o no Facity Controle?",description:"PASSO 1: LOGIN NO SISTEMA Abra o Facity Controle no computador e fa\xe7a o login. > \ud83d\udca1 Aten\xe7\xe3o: O nome da empresa, login e senha devem ser digitados totalmente ..."},c=void 0,i={id:"cadastros/como-adicionar-opcionais-em-uma-secao-no-facity-controle-",title:"Como Adicionar Opcionais em uma Se\xe7\xe3o no Facity Controle?",description:"PASSO 1: LOGIN NO SISTEMA Abra o Facity Controle no computador e fa\xe7a o login. > \ud83d\udca1 Aten\xe7\xe3o: O nome da empresa, login e senha devem ser digitados totalmente ...",source:"@site/docs/cadastros/como-adicionar-opcionais-em-uma-secao-no-facity-controle-.mdx",sourceDirName:"cadastros",slug:"/cadastros/como-adicionar-opcionais-em-uma-secao-no-facity-controle-",permalink:"/docs/cadastros/como-adicionar-opcionais-em-uma-secao-no-facity-controle-",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{title:"Como Adicionar Opcionais em uma Se\xe7\xe3o no Facity Controle?",description:"PASSO 1: LOGIN NO SISTEMA Abra o Facity Controle no computador e fa\xe7a o login. > \ud83d\udca1 Aten\xe7\xe3o: O nome da empresa, login e senha devem ser digitados totalmente ..."},sidebar:"tutorialSidebar",previous:{title:"Como adicionar opcionais ao sabor em produto tipo pizza?",permalink:"/docs/cadastros/como-adicionar-opcionais-ao-sabor-em-produto-tipo-pizza-"},next:{title:"Como adicionar ou alterar os valores em combos?",permalink:"/docs/cadastros/como-adicionar-ou-alterar-os-valores-em-combos-"}},p={},l=[];function r(o){return(0,t.jsx)(t.Fragment,{children:(0,t.jsx)(t.Fragment,{children:(0,t.jsx)("div",{dangerouslySetInnerHTML:{__html:'\n  \n<p></p>\n\n\n\n<h3 class="wp-block-heading"><em><strong>Passo 1: Login no Sistema</strong></em></h3>\n\n\n\n<p>Abra o <strong>Facity Controle</strong> no computador e fa\xe7a o login.</p>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p>\ud83d\udca1 <strong>Aten\xe7\xe3o:</strong> O nome da empresa, login e senha devem ser digitados totalmente em <strong>letras min\xfasculas</strong>.</p>\n</blockquote>\n\n\n\n<figure class="wp-block-image size-full"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="1315" height="621" src="https://manual.facity.com.br/wp-content/uploads/2026/05/CAPAPARAOBLOG.jpg" alt="" class="wp-image-1984" srcset="https://manual.facity.com.br/wp-content/uploads/2026/05/CAPAPARAOBLOG.jpg 1315w, https://manual.facity.com.br/wp-content/uploads/2026/05/CAPAPARAOBLOG-300x142.jpg 300w, https://manual.facity.com.br/wp-content/uploads/2026/05/CAPAPARAOBLOG-1024x484.jpg 1024w, https://manual.facity.com.br/wp-content/uploads/2026/05/CAPAPARAOBLOG-768x363.jpg 768w, https://manual.facity.com.br/wp-content/uploads/2026/05/CAPAPARAOBLOG-720x340.jpg 720w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<h3 class="wp-block-heading"><strong><em>Passo 2: Acesse as Categorias</em></strong></h3>\n\n\n\n<p>No menu principal, clique em <strong>Se\xe7\xf5es/Categorias</strong>.</p>\n\n\n\n<figure class="wp-block-image size-large"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="1024" height="484" src="https://manual.facity.com.br/wp-content/uploads/2026/05/novopocionas-1024x484.png" alt="" class="wp-image-1974" srcset="https://manual.facity.com.br/wp-content/uploads/2026/05/novopocionas-1024x484.png 1024w, https://manual.facity.com.br/wp-content/uploads/2026/05/novopocionas-300x142.png 300w, https://manual.facity.com.br/wp-content/uploads/2026/05/novopocionas-768x363.png 768w, https://manual.facity.com.br/wp-content/uploads/2026/05/novopocionas-720x340.png 720w, https://manual.facity.com.br/wp-content/uploads/2026/05/novopocionas.png 1315w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<h3 class="wp-block-heading"><strong><em>Passo 3: Escolha a Se\xe7\xe3o Desejada</em></strong></h3>\n\n\n\n<p>Localize a categoria que deseja alterar (ex: <em>Hamb\xfargueres</em>) e clique no <strong>bot\xe3o verde (Editar)</strong> ao lado dela.</p>\n\n\n\n<figure class="wp-block-image size-large"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="1024" height="484" src="https://manual.facity.com.br/wp-content/uploads/2026/06/hamburgueejee-1024x484.png" alt="" class="wp-image-1988" srcset="https://manual.facity.com.br/wp-content/uploads/2026/06/hamburgueejee-1024x484.png 1024w, https://manual.facity.com.br/wp-content/uploads/2026/06/hamburgueejee-300x142.png 300w, https://manual.facity.com.br/wp-content/uploads/2026/06/hamburgueejee-768x363.png 768w, https://manual.facity.com.br/wp-content/uploads/2026/06/hamburgueejee-720x340.png 720w, https://manual.facity.com.br/wp-content/uploads/2026/06/hamburgueejee.png 1315w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<h3 class="wp-block-heading"><strong><em>Passo 4: Acesse a \xc1rea de Opcionais</em></strong></h3>\n\n\n\n<p>Dentro da tela de edi\xe7\xe3o da se\xe7\xe3o, clique na aba <strong>Grupos de Opc</strong>.</p>\n\n\n\n<figure class="wp-block-image size-large"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="1024" height="484" src="https://manual.facity.com.br/wp-content/uploads/2026/06/00002-1024x484.png" alt="" class="wp-image-1989" srcset="https://manual.facity.com.br/wp-content/uploads/2026/06/00002-1024x484.png 1024w, https://manual.facity.com.br/wp-content/uploads/2026/06/00002-300x142.png 300w, https://manual.facity.com.br/wp-content/uploads/2026/06/00002-768x363.png 768w, https://manual.facity.com.br/wp-content/uploads/2026/06/00002-720x340.png 720w, https://manual.facity.com.br/wp-content/uploads/2026/06/00002.png 1315w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<p class="has-medium-font-size"><strong><em>Passo 5: Crie o Grupo de Opcionais</em></strong></p>\n\n\n\n<ol class="wp-block-list">\n<li class="has-small-font-size">Clique no bot\xe3o <strong>Novo</strong>.</li>\n\n\n\n<li>Digite o nome do grupo (Ex: <em>Escolha o Molho</em> ou <em>Adicionais do Hamb\xfarguer</em>).</li>\n\n\n\n<li>Se necess\xe1rio, ajuste as <strong>quantidades m\xednima e m\xe1xima</strong> permitidas para o cliente escolher e salve.</li>\n</ol>\n\n\n\n<figure class="wp-block-image size-large"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="1024" height="484" src="https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcio5-1024x484.png" alt="" class="wp-image-1979" srcset="https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcio5-1024x484.png 1024w, https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcio5-300x142.png 300w, https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcio5-768x363.png 768w, https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcio5-720x340.png 720w, https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcio5.png 1315w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<h3 class="wp-block-heading"><strong><em>Passo 6: Adicione os Itens ao Grupo</em></strong></h3>\n\n\n\n<ol start="1" class="wp-block-list">\n<li>Com o grupo que voc\xea acabou de criar selecionado, clique no bot\xe3o <strong>Op\xe7\xf5es</strong>.</li>\n</ol>\n\n\n\n<figure class="wp-block-image size-large"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="1024" height="484" src="https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcpamc6-1024x484.png" alt="" class="wp-image-1980" srcset="https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcpamc6-1024x484.png 1024w, https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcpamc6-300x142.png 300w, https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcpamc6-768x363.png 768w, https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcpamc6-720x340.png 720w, https://manual.facity.com.br/wp-content/uploads/2026/05/novoopcpamc6.png 1315w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<p> 2. Clique em <strong>Novo Opcional</strong>.</p>\n\n\n\n<figure class="wp-block-image size-large"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="1024" height="484" src="https://manual.facity.com.br/wp-content/uploads/2026/05/n-ovopciao7-1024x484.png" alt="" class="wp-image-1981" srcset="https://manual.facity.com.br/wp-content/uploads/2026/05/n-ovopciao7-1024x484.png 1024w, https://manual.facity.com.br/wp-content/uploads/2026/05/n-ovopciao7-300x142.png 300w, https://manual.facity.com.br/wp-content/uploads/2026/05/n-ovopciao7-768x363.png 768w, https://manual.facity.com.br/wp-content/uploads/2026/05/n-ovopciao7-720x340.png 720w, https://manual.facity.com.br/wp-content/uploads/2026/05/n-ovopciao7.png 1315w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<p>3. Preencha o <strong>Nome do adicional</strong> e o <strong>Valor</strong> (deixe R$ 0,00 se for gratuito). Clique em <strong>OK</strong> para salvar.</p>\n\n\n\n<figure class="wp-block-image size-large"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="1024" height="484" src="https://manual.facity.com.br/wp-content/uploads/2026/05/novo\xb4poanso8-1024x484.png" alt="" class="wp-image-1982" srcset="https://manual.facity.com.br/wp-content/uploads/2026/05/novo\xb4poanso8-1024x484.png 1024w, https://manual.facity.com.br/wp-content/uploads/2026/05/novo\xb4poanso8-300x142.png 300w, https://manual.facity.com.br/wp-content/uploads/2026/05/novo\xb4poanso8-768x363.png 768w, https://manual.facity.com.br/wp-content/uploads/2026/05/novo\xb4poanso8-720x340.png 720w, https://manual.facity.com.br/wp-content/uploads/2026/05/novo\xb4poanso8.png 1315w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p>\ud83d\udd04 <strong>Dica:</strong> Repita o <strong>Passo 6</strong> para cada um dos adicionais que deseja incluir nesse grupo.</p>\n\n\n\n<p>\ud83d\udd04 <strong>Dica:</strong> Caso o opcional j\xe1 esteja cadastrado, clique em <strong>Buscar Adicional</strong>.</p>\n</blockquote>\n\n\n\n<p></p>\n\n'}})})})}function m(o={}){const{wrapper:n}={...(0,e.R)(),...o.components};return n?(0,t.jsx)(n,{...o,children:(0,t.jsx)(r,{...o})}):r()}},8453:(o,n,a)=>{a.d(n,{R:()=>c,x:()=>i});var t=a(6540);const e={},s=t.createContext(e);function c(o){const n=t.useContext(s);return t.useMemo((function(){return"function"==typeof o?o(n):{...n,...o}}),[n,o])}function i(o){let n;return n=o.disableParentContext?"function"==typeof o.components?o.components(e):o.components||e:c(o.components),t.createElement(s.Provider,{value:n},o.children)}}}]);